INSERT INTO routes (id, kind, name, region, status, difficulty, distance_km, gain_m, loss_m, date_start, date_end, from_point, to_point, season, forecast_link, bus_link, bdz_link, avtogari_link, route_line, verification_level, transport, huts, risk, days, accommodation, taxis, windy_embed, notes_default) VALUES ('belmeken', 'detailed', 'Белмекен – Юндола – Велинград', 'Рила (юг) / граница с Родопите', 'Идея', 'Среден', 30, 1250, 950, '2026-08-08', '2026-08-09', 'Костенец', 'Велинград', 'Юни – Октомври', 'https://www.google.com/search?q=windy+prognoza+velingrad', 'https://www.busexpress.bg/en/destination/kostenets/velingrad', 'https://razpisanie.bdz.bg/bg/kostenets/velingrad', 'https://avtogari.info/search.php?start=Костенец&end=Велинград', 'Костенец (влак) → х. Белмекен, яз. Белмекен → х. Христо Смирненски → Юндола', 'ДОБРО — потвърден в туристически форум (bulgarian-mountains.com) с точно тази последователност от хижи.', '{"summary":"Влак в двата края (София↔Костенец, Юндола-теснолинейка↔Велинград) — най-удобният вариант транспортно. До х. Христо Смирненски се стига и с кола по асфалт.","car":{"available":true,"text":"До х. Христо Смирненски се стига с кола по асфалтиран път — възможно е такси вместо пешеходната част на ден 2, ако искаш да скъсиш времето.","parkingNote":"Паркинг при хижата; провери проходимост на последните км при дъждовно време."},"public":{"steps":[{"from":"София/Пловдив","to":"Костенец","mode":"Влак (главна линия)","time":"чест / ~1-1.5ч","note":"Костенец е на основната жп линия — лесен достъп."},{"from":"Юндола","to":"Велинград","mode":"Теснолинейка Септември–Велинград–Добринище или автобус","time":"по разписание","note":"Провери час в БДЖ преди тръгване."}]}}'::jsonb, '[{"name":"х. Белмекен","elevation":2208,"beds":39,"officialSource":"БТС официално (btsbg.org, одит 09.07.2026)","officialPhone":"0879 461899","altPhone":"0889 798 586","gps":"42.1930, 23.7495","verified":true,"conflict":"⚠️ РАЗЛИЧАВА СЕ — официалният БТС номер (0879 461899) се разминава с форумния (0889 798 586), както и капацитетът/височината (39 vs 65 места). Обади се на двата преди датата."},{"name":"х. Христо Смирненски","elevation":1758,"beds":60,"officialSource":"БТС официално","officialPhone":"0877 33 29 69","email":"smirnenskihut@gmail.com","gps":"42.1066, 23.7935","verified":true,"conflict":null}]'::jsonb, '{"level":"СРЕДЕН","color":"amber","points":["Терен: Ден 1 (Костенец→х. Белмекен) е най-рисковата част — документиран случай на изгубване (5ч30мин станали 11ч). Задължително следвай р. Крайна и се обади на хижаря преди тръгване.","Транспорт: Добре — влак в двата края, най-удобният вариант от всички нови маршрути.","Хижи: Телефоните на Белмекен и Христо Смирненски са потвърдени от 2+ независими извора, но с разминаване за Белмекен (виж таблицата с хижи).","Километри/денивелация: Среден риск за ден 1 — цифрите са оценка (13-16 км, 1000-1450 м), не точен GPX трак. Провери в OsmAnd/bgmountains преди датата."],"conclusion":"Най-сигурният транспортно от новите маршрути (влак-влак), но ден 1 изисква внимание към ориентирането и предварителен съвет от хижаря."}'::jsonb, '[{"date":"Съб. 08.08","label":"София → Костенец","type":"Транспорт","distance":"70 км с влак","gain":"–","time":"1-1.5ч","stay":"–","difficulty":"–"},{"date":"Съб. 08.08","label":"Костенец → х. Белмекен","type":"Преход","distance":"13-16 км (оценка)","gain":"1000-1450м (оценка)","time":"5-6ч","stay":"х. Белмекен","difficulty":"Среден"},{"date":"Нед. 09.08","label":"х. Белмекен → яз. Белмекен","type":"Преход (кратък спуск)","distance":"1-2 км","gain":"-15-20 мин слизане","time":"15-20мин","stay":"–","difficulty":"Лесен"},{"date":"Нед. 09.08","label":"Яз. Белмекен → х. Хр. Смирненски → Юндола","type":"Преход","distance":"16 км","gain":"+50м / -900м","time":"4.5ч","stay":"–","difficulty":"Лесен"},{"date":"Нед. 09.08","label":"Юндола → Велинград","type":"Транспорт","distance":"25 км","gain":"–","time":"по разписание (теснолинейка/автобус)","stay":"–","difficulty":"–"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'https://embed.windy.com/embed.html?type=map&location=coordinates&metricRain=mm&metricWind=km%2Fh&zoom=10&overlay=rain&product=ecmwf&level=surface&lat=42.0500&lon=23.7500', '⚠️ Задължително обади се на хижаря на х. Белмекен преди тръгване и потвърди актуалното състояние на маркировката за ден 1.'),
('rodopi-orfey', 'detailed', 'Родопи: връх Орфей (+ Каньонът на водопадите)', 'Родопи (Смолян)', 'Планиран', 'Лесен', 19.5, 729, 715, '2026-08-01', '2026-08-02', 'София', 'Смолян', 'Юни – Октомври (сняг по билото до май)', 'https://www.google.com/search?q=windy+prognoza+smolyan', 'https://www.busexpress.bg/en/destination/sofia/smolyan', 'https://razpisanie.bdz.bg/bg/sofia/smolyan', 'https://avtogari.info/search.php?start=София&end=Смолян', 'Каньонът на водопадите (кръгов) – Смолян, Връх Орфей (от параклис след х. Перелик, отиване-връщане)', 'Денивелацията е верифицирана от 2 реални измервания (240м и 280м). Пътят до параклиса потвърден проходим с лека кола от 3+ независими извора.', '{"summary":"Лична кола София↔Смолян (~260 км, ~4-4.5ч). Пътят до х. Перелик/параклиса е проходим с ВСЯКАКВА лека кола — 4x4 не е нужен.","car":{"available":true,"text":"Път до параклиса (1.2 км след х. Перелик): проходим с всякакъв тип лека кола, потвърдено от 3 независими извора (bulgarian-mountains.com, TripJournal, IzBulgaria). Алтернативен маршрут: отбивка Превала (по пътя Смолян–Девин) → 5-6 км до хижата, възможно по-къс от варианта през Стойките.","parkingNote":"⚠️ На паркинга при канйона има хора с джипове, които твърдят, че информационният център е далеч (искат 20 лв превоз) — всъщност е ~15 мин пеша, спести парите."},"public":{"steps":[{"from":"София","to":"Смолян/Езерово","mode":"Автобус","time":"~4-4.5ч","note":"С кола таксито става излишно — виж таксиметрова таблица по-долу само ако пътуваш без кола."}]}}'::jsonb, '[{"name":"х. Перелик","elevation":1969,"beds":35,"officialSource":"ПОТВЪРДЕНО от БТС (одит 09.07.2026)","officialPhone":"0988 800 850","contactName":"Илия Чернев (председател ТД „Перелик“ – Широка лъка)","altPhone":"0886 675 111 (Янко Пелтеков, за контакти)","gps":"41.610195, 24.596352","verified":true,"conflict":null,"staleNumbers":"Старите номера (0886 752 111 / 0889 371 409) са устарели — не са в официалния БТС профил."}]'::jsonb, '{"level":"НИСЪК","color":"emerald","points":["Терен: оценен от местни като „най-лекият от всички родопски първенци и най-маркираният“. Нетото покачване параклис→връх е само +188м, реалното кумулативно е по-голямо заради подсичане на Малък Перелик и Шабалиева Каба.","Сезонност: комент от май 2026 — по склоновете на Голям Перелик все още имало сняг (метър преспи на места). Извън планирания период, но провери свежи отзиви близо до датата.","Паркинг измами: на паркинга при канйона има хора с джипове, предлагащи ненужен превоз до информационния център (~15 мин пеша).","Данни за денивелация: верифицирани от 2 реални измервания (240м и 280м), средна стойност 265м."],"conclusion":"Най-лекият и най-сигурен от планираните преходи — основното внимание е към сезонния сняг по билото и паркинг измамите."}'::jsonb, '[{"date":"Съб. 01.08","label":"София → Смолян/Езерово","type":"Транспорт","distance":"260 км с кола","gain":"–","time":"4-4.5ч","stay":"х. Кристал, Езерово","difficulty":"–"},{"date":"Съб. 01.08","label":"Каньонът на водопадите (кръгов)","type":"Преход","distance":"кръгов, 4 етапа","gain":"не е дадено","time":"3ч","stay":"х. Кристал, Езерово","difficulty":"Лесен"},{"date":"Нед. 02.08","label":"Параклис (след х. Перелик) → връх Орфей → обратно","type":"Преход","distance":"~13 км (туристическа оценка)","gain":"265м всяка посока","time":"5ч с почивки","stay":"–","difficulty":"Лесен"},{"date":"Нед. 02.08","label":"Смолян/Езерово → София","type":"Транспорт","distance":"260 км с кола","gain":"–","time":"4-4.5ч","stay":"–","difficulty":"–"}]'::jsonb, '[{"name":"Семеен хотел Кристал","location":"кв. Езерово, на брега на Керянов гьол","rating":"8.4 (Booking)","price":"80 лв двойна стая","note":"Гледка към скала Невястата; за вечеря наблизо — ресторант Рибката."},{"name":"Хотел Кипарис Алфа","location":"центъра на Смолян","rating":"9.1 (Booking)","price":"120 лв двойна със закуска","note":"По-скъп, но топ локация."}]'::jsonb, '[{"name":"Експрес такси","phone":"0301 6147","note":"Обслужва изрично Смолян, с. Стойките, Широка лъка, Чепеларе, Пампорово — най-вероятният кандидат."},{"name":"Хит такси","phone":"0878 166 161 / 0886 668 866","note":"–"},{"name":"Такси 1 Плюс","phone":"0301 6188","note":"–"},{"name":"Радиотакси","phone":"0301 35059","note":"–"},{"name":"Узунов Трансгруп","phone":"0301 82647","note":"–"}]'::jsonb, 'https://embed.windy.com/embed.html?type=map&location=coordinates&metricRain=mm&metricWind=km%2Fh&zoom=10&overlay=rain&product=ecmwf&level=surface&lat=41.6100&lon=24.5960', '💡 Извор на река Арда е ~35 км в обратна посока — не е включен в плана, защото не се съчетава лесно с връх Орфей в един уикенд.'),
('bezbog-popovo-ezero', 'detailed', 'Хижа „Безбог“ – Попово езеро', 'Пирин', 'Идея', 'Лесна', 7.4, 223, 214, '', '', 'Добринище', 'Добринище', 'Юни – Октомври (лифтът работи целогодишно, зимата — само с опит и разрешителни за НП Пирин)', 'https://www.google.com/search?q=windy+prognoza+bezbog', 'https://www.virail.bg/avtobus-dobrinische-bansko', '', 'https://avtogari.info/search.php?start=София&end=Добринище', 'Добринище (лифт) → х. Гоце Делчев → х. Безбог → Безбожко езеро → Попово езеро → обратно', 'СРЕДНО — разстоянието/денивелацията са от еднопосочен туристически справочник (planinka.bg), не от GPX трак. Телефонът на хижата се разминава между източниците (виж huts.conflict).', '{"summary":"Без директен път за кола до самата хижа — задължителен седалков лифт от Добринище до х. Гоце Делчев, оттам пеша до х. Безбог.","car":{"available":false,"text":"Кола стига само до долната лифтова станция в Добринище. Оттам няма алтернатива на лифта или дълъг пешеходен подход.","parkingNote":"Паркинг при долната станция — безплатен, но неохраняван. Форумни отзиви (bulgarian-mountains.com) съобщават, че оставяне на кола за 4-5 дни е било безопасно, но това не е гаранция."},"public":{"steps":[{"from":"Банско","to":"Добринище","mode":"Автобус (Union Ivkoni / Struma 11)","time":"15-20 мин, чести курсове 08:30-19:48ч","note":"Провери актуално разписание преди тръгване."},{"from":"Добринище","to":"х. Гоце Делчев","mode":"Седалков лифт","time":"27 мин, 3245м, работи 08:30-17:00ч (посл. качване 16:45ч)","note":"12 лв еднопосочно / 18 лв двупосочно (цени 2020г. — провери актуални)."},{"from":"х. Гоце Делчев","to":"х. Безбог","mode":"Пеша","time":"~30-40 мин","note":"Кратък и лек преход между двете хижи."}]}}'::jsonb, '[{"name":"х. Безбог","elevation":2240,"beds":null,"officialSource":"explorebg.com","officialPhone":"+359 74 472120","altPhone":"0888 286 102","gps":"41.733889, 23.524167","verified":true,"conflict":"⚠️ Двата телефона идват от различни източници (explorebg.com срещу предишен запис в базата) — обади се на explorebg номера първо и провери и двата преди датата."}]'::jsonb, '{"level":"НИСЪК","color":"emerald","points":["Терен: оценен като 2/6 (лесно) — широка, добре маркирана зелена пътека, с кратки каменисти участъци.","Логистика: единственият достъп е лифтът — провери работното време и последно качване (16:45ч) преди да планираш деня.","Вода: няма чешми по пътеката — носи поне 1.5л на човек.","Данни: разстоянието/денивелацията са от единичен източник (planinka.bg), не от верифициран GPX — третирай ги като добра, но не абсолютна оценка."],"conclusion":"Най-лекият от трите нови маршрута — основното внимание е към часовете на лифта, не към самия терен."}'::jsonb, '[{"date":"Ден 1","label":"Добринище → лифт → х. Гоце Делчев → х. Безбог","type":"Транспорт + кратък преход","distance":"лифт 3.2км + пеша ~1км","gain":"737м (лифт) + малко пеша","time":"27 мин лифт + 30-40 мин пеша","stay":"х. Безбог","difficulty":"Лесен"},{"date":"Ден 2","label":"х. Безбог → Попово езеро → обратно → лифт надолу","type":"Преход","distance":"7.4 км (там и обратно)","gain":"223м / -214м","time":"~2ч40мин ходене + почивки","stay":"–","difficulty":"Лесен"}]'::jsonb, '[{"name":"х. Безбог","location":"на място, 2240м н.в.","rating":null,"price":null,"note":"Основна нощувка на маршрута — резервирай предварително по телефон."}]'::jsonb, '[]'::jsonb, 'https://embed.windy.com/embed.html?type=map&location=coordinates&metricRain=mm&metricWind=km%2Fh&zoom=11&overlay=rain&product=ecmwf&level=surface&lat=41.7339&lon=23.5242', '⚠️ Обади се на хижа Безбог (+359 74 472120) преди тръгване, за да провериш разписанието на лифта и наличността на места.')
